      "options": [],
      "answer": "1. 优点：①能够严格操纵自变量、控制无关变量，是探讨变量间因果关系的唯一方法；②能够主动创设实验情境，便于重复验证。\n2. 缺点：①实验室的人工情境可能导致被试紧张不自然，生态效度受限；②受伦理或技术限制，许多高级社会心理现象（如创伤、家庭离异）无法人为操纵。\n3. 控制无关变量技术：①消除法（隔音隔光排除干扰）；②恒定法（保持各组指导语、主试、测试环境完全一致）；③平衡/随机化法（随机分配被试消除机体变量，采用拉丁方抵消顺序效应）。",
