      "options": [],
      "answer": "1. 知觉四大特征：\n① 选择性（对象性）：把某些刺激从背景中优先区分出来进行加工。如喧闹考场中听到考官翻卷子声；\n② 整体性：依据刺激的空间结构将碎片整合为有机完形。如漫画只需几笔勾勒即知是某名人；\n③ 理解性：利用已有知识经验去解释当前知觉对象并赋予概念。如专业技工凭发动机声音辨识故障；\n④ 恒常性：物理刺激在一定范围内改变，知觉映象保持相对稳定。如斜开的门仍被感知为长方形。\n2. 相互关系：\n• 选择性是知觉加工的前提，确定了知觉对象；\n• 整体性是知觉加工的核心结构组织；\n• 理解性为整体知觉提供语义指导并提高加工速度；\n• 恒常性维持了知觉对物理世界的稳定表征，使人类不致因光线或视角改变而发生认知错乱。",
