      "options": [],
      "answer": "1. 区别：\n• 概念本质：语言是一种社会历史现象，是由词汇和语法规则构成的客观符号系统，作为人类保存和传递社会历史经验的工具；言语则是运用语言符号进行思想交流和信息传递的个体心理活动过程。\n• 社会性 vs 个体性：语言是社会全民族约定俗成共有的，具有社会性与客观规范性；言语是个体对语言的具体运用，具有个体心理差异性（体现个人的情绪、气质、表达风格）。\n• 稳定性 vs 动态性：语言系统规则相对稳定缓慢演变；言语活动则是随着交流情境瞬息万变的动态心理过程。\n2. 联系：\n• 言语离不开语言：言语活动必须借助某种既定的语言符号系统才能实现沟通理解；\n• 语言存在于言语之中：语言是在千百万人丰富动态的言语交际实践中产生、发展、丰富并沉淀下来的，脱离了言语活动的语言就会变成‘死语言’。",
