      "options": [],
      "answer": "1. 詹姆斯-兰格理论（外周自主神经论）：\n• 核心观点：情绪是对身体生理和内脏变化的知觉感受，‘因为哭泣所以悲伤，因为奔跑所以恐惧’。\n• 局限：颠倒了因果关系；切断外周交感神经的动物依然能表现出情绪，证明外周生理唤醒非唯一因。\n2. 坎农-巴德理论（丘脑中枢论）：\n• 核心观点：情绪中枢在丘脑。外界刺激经丘脑中转，一条通路上传至大脑皮层产生主观体验，另一条下行至自主神经产生生理唤醒，两者几乎同时独立发生。\n• 进步：纠正了外周因果谬误，强调了中枢神经系统在情绪中的决定作用。\n3. 沙赫特-辛格双因素理论（认知生理评价论）：\n• 核心观点：单纯的生理唤醒或单纯的认知都不能单独构成情绪，情绪是生理唤醒与环境认知评价的乘积。当机体处于不可解释的高唤醒时，大脑会主动搜寻外部环境线索进行解释赋予具体情绪色彩。\n• 贡献：将情绪研究从纯生理机制推向认知神经互动的高级维度。",
      "explanation": "",
