      "title": "详述弗洛伊德精神分析的人格结构理论（本我、自我、超我），并列举阐述五种主要的自我防御机制。",
      "options": [],
      "answer": "1. 人格三大系统结构：\n• 本我（Id）：处于潜意识深处，由遗传的原始本能欲望（生本能与死本能）构成。遵循‘快乐原则’，盲目寻求即时冲动满足，无逻辑无时间概念。\n• 自我（Ego）：从本我中分化出来的意识理智中枢。遵循‘现实原则’，充当调停者，在外界现实约束、本我本能冲动与超我道德训诫之间寻求理性平衡。\n• 超我（Superego）：社会道德教化的内化沉淀，包含良心和自我理想。遵循‘道德原则/完美原则’，对自我的行为进行道德审查与奖惩。\n2. 五种核心自我防御机制（得分点）：\n① 压抑（Repression）：最基本的机制。把引发强烈痛苦焦虑的创伤经验驱逐至潜意识深处封存；\n② 投射（Projection）：以己度人，把自己潜意识中不可见人的不良动机强加于他人身上；\n③ 合理化（Rationalization）：寻找冠冕堂皇的虚假借口为自身挫折或行为辩解（如酸葡萄与甜柠檬效应）；\n④ 置换/转移（Displacement）：将对高威胁对象的攻击情绪转向无辜、弱小安全的替代对象；\n⑤ 升华（Sublimation）：最高级健康的机制。将原始具有破坏性的本能冲动升华为社会认可赞赏的崇高文化、科学创造或体育运动。",
