      "title": "对比自陈式人格测验（如MMPI、16PF）与投射式人格测验（如罗夏墨迹测验、TAT）的测验原理、施测方式与各自的优缺点。",
      "options": [],
      "answer": "1. 测验原理与材料对比：\n• 自陈量表：建立在特质论基础上，采用结构高度明确的书面陈述题（如‘我常常失眠：是/否’），由被试根据自身实际情况做出自我评定报告；\n• 投射测验：建立在精神分析潜意识投射机制上，采用结构模糊、歧义性极高的人工刺激（墨渍或模糊人物画片），让被试在没有标准答案的情境下自由联想编造故事，将深层被压抑的欲望、动机和创伤投射出来。\n2. 优缺点对比：\n• 自陈量表优点：施测方便快捷，可大样本集体施测；评分客观标准化，信度与效度系数通常较高；\n• 自陈量表缺点：题目用意透明，被试极易产生‘社会赞许性掩饰’（挑好听的说）或装病，且只能测查被试有意识觉知的心理特质；\n• 投射测验优点：刺激模糊，被试很难猜透测试真实意图从而无法刻意伪装，能够穿透意识防御深入测查深层无意识人格动力；\n• 投射测验缺点：施测对主试专业临床经验要求极高；计分和解释带有极强的主观经验色彩，重测信度与实证效度长期受测量学质疑，标准化成本巨大。",
