      "answer": "1. 可复制性（可重验性）：一项科学研究的结果能够按照原创者所提供的实验条件、控制变量与测试程序精确重复验证（2024选真题）。\n2. 可证伪性：在表述一个科学理论时，必须遵循该理论推导出的各种预测有可能在经验上被反例所推翻，理论必须具备可检验性（波普尔科学哲学准则）。\n3. 系统性：心理学研究不是孤立事实的罗列堆砌，而是必须置于连贯一致的理论框架与严谨的因果逻辑体系之中，接受同行评议与交叉验证。",
