      "sourceTag": "【格式塔原则大题必背】",
      "answer": "1. 接近原则（Proximity）：在空间或时间上彼此接近的刺激碎片更容易被组合为一个知觉整体（如几排间距密集的点被看作一条条横线）。\n2. 相似原则（Similarity）：在物理属性（形状、颜色、大小、明度）上相似的元素更容易被组合成一组（如黑白相间的方块阵列会被知觉为黑白垂直条带）。\n3. 连续原则（Good Continuation）：视野中的线段具有保持原有运动方向或曲率平滑延续的倾向，相交的线条被知觉为连续平滑的独立曲线，而非急转弯的折角。\n4. 闭合原则（Closure）：人类知觉倾向于自动填补客观轮廓存在的微小缺口，将残缺或不连续的图形感知为一个完整封闭的几何实体（如缺口圆依然被知觉为圆形）。\n5. 共同命运原则（Common Fate）：朝着同一空间方向运动或发生同步变化的元素，容易被组织为一个运动整体（如草丛中同步起飞的惊鸟群）。",
