      "answer": "1. 共同维度与判别标准：\n• 目标维度：强化（无论正负）旨在【提高】行为发生率；惩罚（无论正负）旨在【降低】行为发生率。\n• 刺激操纵：正（Positive）代表【呈现/施加】刺激；负（Negative）代表【撤销/剥夺】刺激。\n2. 四大概念与实例对比：\n① 正强化：呈现愉快刺激以增加行为。例：考了满分奖励自行车，学习更刻苦。\n② 负强化：撤销厌恶刺激以增加行为。例：系好安全带消除刺耳蜂鸣警报，系安全带行为增加。\n③ 正惩罚：呈现厌恶刺激以减少行为。例：上课讲话老师罚抄课文，讲话减少。\n④ 负惩罚：撤销愉快刺激以减少行为。例：青少年沉迷游戏旷课，父母切断WiFi并没收手机，旷课减少。",
