      "sourceTag": "【班杜拉社会学习必背大题】",
      "answer": "1. 观察学习的核心观点：班杜拉通过波波玩偶实验证实，人类的大多数行为并非仅仅通过直接试误和直接强化习得，而是通过在社会环境中观察榜样（Model）的行为及其产生的后果而进行的替代学习（Vicarious Learning）。\n2. 观察学习的四个心理子过程：\n① 注意过程：注意并知觉榜样行为的显著特征；\n② 保持过程：头脑中以言语表象符号形式表征并储存行为模式；\n③ 动作复现过程：将内部表象转化为外显动作，对照反馈反复纠正；\n④ 动机过程：决定习得的行为是否付诸现实外显执行。受强化驱动。\n3. 三种强化形式：\n• 直接强化：观察者自己做出行为后亲身受到的外部直接奖惩；\n• 替代强化：看到榜样做出行为受到奖惩，间接强化或抑制自身行为；\n• 自我强化：个体根据自己设立的内部崇高标准对自身行为进行自我评价与精神奖赏。",
