      "sourceTag": "【现代认知心理学前沿必背大题】",
      "answer": "1. 中央执行系统（Central Executive）：工作记忆的核心与中枢调控者。功能：控制和协调注意资源分配；监督并调控下属子系统的工作流程；在不同任务之间灵活切换注意力；从长时记忆中主动提取与当前任务相关的知识图式。\n2. 语音回路（Phonological Loop）：负责以语音和声音为基础的信息的储存与加工。包含两部分：①语音存储（以声学编码暂时保留语音痕迹约1.5-2秒）；②发音复述机制（类似默读的心智发音，能不断刷新并维持语音痕迹防止衰退）。\n3. 视空间画板（Visuospatial Sketchpad）：负责视觉表象、空间位置、物体形状和三维方位的心理操作与动态旋转加工（如心智旋转任务）。\n4. 情景缓冲器（Episodic Buffer）：巴德利于2000年补充的第四成分。是一个容量受限的独立系统，负责跨模态整合来自语音回路、视空间画板以及长时记忆中的各种信息，构建统合的连贯情景表征。",
