      "sourceTag": "【2017选、2023J、2024选核心大题】",
      "answer": "1. 适应功能（生存演化）：情绪是有机体适应生存环境、繁衍进化的工具。例如：在远古森林面对猛兽时的恐惧和狂奔逃生，使人类祖先躲避灾难存活下来；婴儿的啼哭能促使父母给予哺乳和照料。\n2. 动机功能（行为催化剂）：情绪是行为的内在动力源泉，对行动具有激活、驱动和维持作用。例如：对知识的强烈求知欲与好奇心能驱使科学家常年耐住寂寞埋头攻关；适度的考前焦虑能激发高效学习背诵动力。\n3. 组织功能（认知调节）：情绪充当了认知活动的组织协调者，正性积极情绪能够拓宽注意广度、激发创造性联想；过度消极压抑的情绪会导致注意狭窄、阻碍记忆与思维决策。\n4. 信号交流功能（社会交往）：情绪通过面部表情、身体姿态和言语声调传递内部心理状态，是人际沟通的重要非言语交流工具。例如：国际通用的微笑能瞬间打破跨文化人际壁垒，表达善意与合作倾向。",
