      "sourceTag": "【大题核心必背·理论流派全面比较】",
      "answer": "1. 詹姆斯-兰格理论（外周生理论）：\n• 刺激 ➔ 生理唤醒与内脏反应 ➔ 情绪体验（“因为哭泣所以悲伤”）。情绪是对身体变化的知觉感受。\n2. 坎农-巴德理论（丘脑中枢论）：\n• 刺激 ➔ 丘脑中转 ➔ 同时独立向皮层发射产生体验、向下丘脑发射产生生理唤醒，两者并行无因果。\n3. 沙赫特-辛格理论（认知生理双因素论）：\n• 情绪是生理唤醒（激活能量）与认知评价（定性解释）的乘积。肾上腺素注射实验证实环境线索认知决定情绪性质。\n4. 阿诺德“评定-兴奋说”：\n• 刺激 ➔ 感觉中枢 ➔ 大脑皮层进行【利害评价】 ➔ 下丘脑兴奋 ➔ 激发具体情绪与面部表情。",
